def resolve_wildcards(text: str) -> str:
    """Repeatedly resolve { a | b | c } groups until none remain."""
    pattern = re.compile(r"\{([^{}]+?)\}")
    while True:
        match = pattern.search(text)
        if not match:
            break
        options = [o.strip() for o in match.group(1).split("|")]
        text = text[: match.start()] + random.choice(options) + text[match.end() :]
    return text


# ── API prompt builder ────────────────────────────────────────────────────────

def build_api_prompt(seed: int) -> dict:
    return {
        "63": {  # VAELoader
            "class_type": "VAELoader",
            "inputs": {"vae_name": "ae.safetensors"},
        },
        "66": {  # UNETLoader
            "class_type": "UNETLoader",
            "inputs": {
                "unet_name": "z_image_turbo_bf16.safetensors",
                "weight_dtype": "default",
            },
        },
        "62": {  # CLIPLoader
            "class_type": "CLIPLoader",
            "inputs": {
                "clip_name": "qwen_3_4b.safetensors",
                "type": "lumina2",
                "device": "default",
            },
        },
        "71": {  # LoraLoader
            "class_type": "LoraLoader",
            "inputs": {
                "model": ["66", 0],
                "clip": ["62", 0],
                "lora_name": "hari_v1.safetensors",
                "strength_model": 1,
                "strength_clip": 1,
            },
        },
        "67": {  # CLIPTextEncode (positive)
            "class_type": "CLIPTextEncode",
            "inputs": {
                "clip": ["71", 1],
                "text": resolve_wildcards(RAW_PROMPT_TEXT),
            },
        },
        "64": {  # ConditioningZeroOut (negative)
            "class_type": "ConditioningZeroOut",
            "inputs": {"conditioning": ["67", 0]},
        },
        "68": {  # EmptySD3LatentImage
            "class_type": "EmptySD3LatentImage",
            "inputs": {"width": 1024, "height": 1024, "batch_size": 1},
        },
        "69": {  # ModelSamplingAuraFlow
            "class_type": "ModelSamplingAuraFlow",
            "inputs": {"shift": 3, "model": ["71", 0]},
        },
        "70": {  # KSampler
            "class_type": "KSampler",
            "inputs": {
                "seed": seed,
                "steps": 8,
                "cfg": 1,
                "sampler_name": "res_multistep",
                "scheduler": "simple",
                "denoise": 1,
                "model": ["69", 0],
                "positive": ["67", 0],
                "negative": ["64", 0],
                "latent_image": ["68", 0],
            },
        },
        "65": {  # VAEDecode
            "class_type": "VAEDecode",
            "inputs": {"samples": ["70", 0], "vae": ["63", 0]},
        },
        "9": {  # SaveImage
            "class_type": "SaveImage",
            "inputs": {
                "filename_prefix": str(seed),
                "images": ["65", 0],
            },
        },
    }


# ── ComfyUI helpers ───────────────────────────────────────────────────────────

def queue_prompt(api_prompt: dict, client_id: str) -> dict:
    payload = {"prompt": api_prompt, "client_id": client_id}
    response = requests.post(f"{COMFYUI_URL}/prompt", json=payload)
    response.raise_for_status()
    return response.json()


def get_image(filename: str, subfolder: str, folder_type: str) -> bytes:
    params = {"filename": filename, "subfolder": subfolder, "type": folder_type}
    response = requests.get(f"{COMFYUI_URL}/view", params=params)
    response.raise_for_status()
    return response.content


def get_history(prompt_id: str) -> dict:
    response = requests.get(f"{COMFYUI_URL}/history/{prompt_id}")
    response.raise_for_status()
    return response.json()


def wait_for_completion(ws: websocket.WebSocket, prompt_id: str) -> bool:
    """Block until the prompt finishes. Returns True on success, False on error."""
    while True:
        out = ws.recv()
        if isinstance(out, str):
            message = json.loads(out)
            msg_type = message.get("type", "")
            data = message.get("data", {})

            if msg_type == "executing":
                if data.get("prompt_id") == prompt_id and data.get("node") is None:
                    return True  # done
            elif msg_type == "progress":
                value = data.get("value", 0)
                max_val = data.get("max", 1)
                print(f"  progress: {value}/{max_val}", end="\r")
            elif msg_type == "execution_error":
                if data.get("prompt_id") == prompt_id:
                    print(f"\n  ERROR: {data.get('exception_message', 'unknown')}")
                    return False
        # binary frames (previews) are silently ignored


# ── Main ─────────────────────────────────────────────────────────────────────

def main() -> None:
    os.makedirs(SAVE_DIR, exist_ok=True)

    print("=" * 60)
    print("  ComfyUI Batch Image Generator — hari_wildcard")
    print("=" * 60)
    print(f"  Save dir : {SAVE_DIR}")
    print(f"  Images   : {NUM_IMAGES}")
    print(f"  Server   : {COMFYUI_URL}")
    print()

    # Verify server connectivity
    try:
        resp = requests.get(f"{COMFYUI_URL}/system_stats", timeout=10)
        resp.raise_for_status()
        print("Server connection OK")
    except Exception as exc:
        print(f"Cannot reach ComfyUI server: {exc}")
        sys.exit(1)

    client_id = f"batch_{random.randint(0, 999999):06d}"

    # WebSocket connection
    ws_url = COMFYUI_URL.rstrip("/").replace("https://", "wss://").replace("http://", "ws://")
    ws = websocket.WebSocket()
    ws.connect(f"{ws_url}/ws?clientId={client_id}")
    print(f"WebSocket connected (client_id: {client_id})\n")

    successful = 0
    failed = 0

    for i in range(1, NUM_IMAGES + 1):
        seed = random.randint(0, 2**53 - 1)
        print(f"[{i:>3}/{NUM_IMAGES}] seed={seed}")

        api_prompt = build_api_prompt(seed)

        try:
            result = queue_prompt(api_prompt, client_id)
            prompt_id = result["prompt_id"]
            print(f"  queued  prompt_id={prompt_id}")

            print(f"  waiting...", end="")
            ok = wait_for_completion(ws, prompt_id)

            if not ok:
                failed += 1
                print()
                continue

            print(f"\r  done              ")

            time.sleep(0.5)
            history = get_history(prompt_id)

            if prompt_id in history:
                outputs = history[prompt_id].get("outputs", {})
                if "9" in outputs:
                    for img_info in outputs["9"].get("images", []):
                        img_bytes = get_image(
                            img_info["filename"],
                            img_info.get("subfolder", ""),
                            img_info.get("type", "output"),
                        )
                        save_path = os.path.join(SAVE_DIR, f"{seed}.png")
                        with open(save_path, "wb") as f:
                            f.write(img_bytes)
                        print(f"  saved  {save_path}  ({len(img_bytes)//1024} KB)")
                        successful += 1
                else:
                    print("  WARNING: SaveImage output not found in history")
                    failed += 1
            else:
                print("  WARNING: prompt_id not in history")
                failed += 1

        except Exception as exc:
            print(f"  ERROR: {exc}")
            failed += 1

        print()

    ws.close()

    print("=" * 60)
    print(f"  Done!  success={successful}  failed={failed}")
    print(f"  Saved to: {SAVE_DIR}")
    print("=" * 60)


if __name__ == "__main__":
    main()
